<?php require_once __DIR__.'/../includes/layout.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$status=$_POST['estado']??'';if(in_array($status,['registrada','aceptada','entregada'],true)){db()->prepare('UPDATE donaciones SET estado=? WHERE id=?')->execute([$status,$id]);flash('success','Donación actualizada.');}go('admin/donaciones.php');}
$items=all('SELECT d.*,u.nombre,u.apellido_paterno,u.telefono FROM donaciones d JOIN pacientes p ON p.id=d.paciente_id JOIN usuarios u ON u.id=p.usuario_id ORDER BY d.id DESC LIMIT 300');header_ui('Donaciones');?><div class="page-intro"><h2>Donaciones de la comunidad 💗</h2><p>Consulta ofrecimientos de aparatos ortopédicos, equipos de movilidad, sangre y medicamentos. Cada ofrecimiento requiere evaluación antes de aceptarse.</p></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Paciente</th><th>Categoría</th><th>Descripción</th><th>Estado</th></tr></thead><tbody><?php foreach($items as $r):?><tr><td><?=e($r['nombre'].' '.$r['apellido_paterno'])?><br><small><?=e($r['telefono'])?></small></td><td><?=e($r['tipo'])?></td><td><?=e($r['descripcion'])?></td><td><form method="post" class="uc-inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="estado"><option value="registrada" <?=$r['estado']==='registrada'?'selected':''?>>Registrada</option><option value="aceptada" <?=$r['estado']==='aceptada'?'selected':''?>>Aceptada</option><option value="entregada" <?=$r['estado']==='entregada'?'selected':''?>>Entregada</option></select><button class="btn btn-sm btn-primary">Guardar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><div class="alert alert-info">Las donaciones de sangre y medicamentos requieren validación sanitaria y procedimientos propios del centro médico; no son intercambios directos entre particulares.</div><?php footer_ui(); ?>
